SELECT i.i_brand, SUM(cs.cs_net_profit) AS total_profit, (SELECT p2.p_promo_name FROM promotion p2 WHERE p2.p_promo_sk = cs.cs_promo_sk AND p2.p_discount_active = 'N') AS active_promo_name FROM catalog_sales cs JOIN item i ON cs.cs_item_sk = i.i_item_sk JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk JOIN web_sales ws ON ws.ws_item_sk = i.i_item_sk WHERE cs.cs_sold_date_sk = 2450824 GROUP BY i.i_brand, cs.cs_promo_sk HAVING COUNT(cs.cs_order_number) > 22
